class CircularDependencyError(Exception):
    """Raised when a circular dependency is detected."""
    pass


class DependencyResolver:
    """Resolves task dependencies into parallel execution stages."""

    def resolve(self, dependencies: dict[str, list[str]]) -> list[list[str]]:
        """
        Resolves task dependencies into parallel execution stages.

        :param dependencies: Mapping of task_name -> list of task_names it depends on.
        :return: List of stages, each containing a sorted list of task names.
        :raises CircularDependencyError: If a circular dependency or self-loop exists.
        """
        # Collect all tasks (explicit keys and any tasks referenced in dependencies)
        all_tasks = set(dependencies.keys())
        for deps in dependencies.values():
            all_tasks.update(deps)

        # Track remaining unfulfilled dependencies for each task
        remaining_deps: dict[str, set[str]] = {
            task: set(dependencies.get(task, [])) for task in all_tasks
        }

        # Map each task to the tasks that depend on it
        dependents: dict[str, set[str]] = {task: set() for task in all_tasks}
        for task, deps in remaining_deps.items():
            for dep in deps:
                dependents[dep].add(task)

        stages: list[list[str]] = []
        resolved_count = 0
        total_tasks = len(all_tasks)

        while resolved_count < total_tasks:
            # Stage contains all tasks whose dependencies are fully resolved
            current_stage = sorted(
                task for task, deps in remaining_deps.items() if len(deps) == 0
            )

            if not current_stage:
                raise CircularDependencyError("Circular dependency detected among tasks.")

            stages.append(current_stage)
            resolved_count += len(current_stage)

            # Remove resolved tasks and update dependent tasks
            for task in current_stage:
                del remaining_deps[task]
                for dependent in dependents[task]:
                    if dependent in remaining_deps:
                        remaining_deps[dependent].discard(task)

        return stages
