import asyncio
import inspect
from typing import Any, Callable, List, Optional


class AsyncWorkerPool:
    """An asynchronous worker pool using standard asyncio with priority queueing,

    graceful draining, and timeout-based shutdown.
    """

    def __init__(self, concurrency: int = 3, max_queue_size: int = 100) -> None:
        if concurrency < 1:
            raise ValueError("concurrency must be at least 1")
        if max_queue_size < 1:
            raise ValueError("max_queue_size must be at least 1")

        self.concurrency: int = concurrency
        self.max_queue_size: int = max_queue_size

        self._queue: asyncio.PriorityQueue = asyncio.PriorityQueue(
            maxsize=max_queue_size
        )
        self._workers: List[asyncio.Task] = []
        self._is_running: bool = False
        self._is_shutting_down: bool = False
        self._counter: int = 0

    async def start(self) -> None:
        """Spawns the pool worker tasks."""
        if self._is_running:
            return

        self._is_running = True
        self._is_shutting_down = False
        self._workers = [
            asyncio.create_task(
                self._worker_loop(), name=f"AsyncWorkerPool-Worker-{i}"
            )
            for i in range(self.concurrency)
        ]

    async def submit(
        self,
        coro_func: Callable[..., Any],
        *args: Any,
        priority: int = 0,
        **kwargs: Any,
    ) -> asyncio.Future:
        """Enqueues a coroutine function to be executed by pool workers.

        Higher priority integers execute before lower priority integers.
        Returns an asyncio.Future that resolves with the result (or exception).
        """
        if self._is_shutting_down:
            raise RuntimeError("Pool is shutting down")

        loop = asyncio.get_running_loop()
        future: asyncio.Future = loop.create_future()

        self._counter += 1
        # Store as (-priority, counter, payload) so highest priority is popped first
        # and ties are resolved in FIFO order without comparing payload objects.
        item = (-priority, self._counter, (coro_func, args, kwargs, future))

        try:
            await self._queue.put(item)
        except Exception:
            if not future.done():
                future.cancel()
            raise

        if self._is_shutting_down:
            if not future.done():
                future.cancel()
            raise RuntimeError("Pool is shutting down")

        return future

    async def _worker_loop(self) -> None:
        """Internal loop executed by each worker task."""
        while True:
            try:
                _, _, (coro_func, args, kwargs, future) = (
                    await self._queue.get()
                )
            except asyncio.CancelledError:
                break

            try:
                if not future.done():
                    result = coro_func(*args, **kwargs)
                    if inspect.isawaitable(result):
                        result = await result
                    if not future.done():
                        future.set_result(result)
            except asyncio.CancelledError:
                if not future.done():
                    future.cancel()
                raise
            except BaseException as exc:
                if not future.done():
                    future.set_exception(exc)
            finally:
                self._queue.task_done()

    def _cancel_queued(self) -> None:
        """Cancels all pending items in the queue and marks them as done."""
        while not self._queue.empty():
            try:
                _, _, (_, _, _, future) = self._queue.get_nowait()
                if not future.done():
                    future.cancel()
                self._queue.task_done()
            except (asyncio.QueueEmpty, ValueError):
                break

    async def shutdown(
        self, drain: bool = True, timeout: Optional[float] = 5.0
    ) -> None:
        """Shuts down the pool.

        If drain=True, waits for queued tasks to finish before stopping workers.
        If drain=False, immediately cancels queued and running tasks.
        Respects the optional timeout in seconds.
        """
        self._is_shutting_down = True

        async def _do_shutdown() -> None:
            if drain:
                await self._queue.join()
            else:
                self._cancel_queued()

            for worker in self._workers:
                worker.cancel()

            if self._workers:
                await asyncio.gather(*self._workers, return_exceptions=True)

        try:
            if timeout is not None:
                await asyncio.wait_for(_do_shutdown(), timeout=timeout)
            else:
                await _do_shutdown()
        except asyncio.TimeoutError:
            # Force cancel all remaining work on timeout
            self._cancel_queued()
            for worker in self._workers:
                worker.cancel()
            if self._workers:
                await asyncio.gather(*self._workers, return_exceptions=True)
        finally:
            self._is_running = False
            self._workers.clear()

    async def __aenter__(self) -> "AsyncWorkerPool":
        await self.start()
        return self

    async def __aexit__(self, exc_type: Any, exc_val: Any, exc_tb: Any) -> None:
        await self.shutdown(drain=True)
