from typing import Any


class QuorumCluster:
    def __init__(self, node_ids: list[str]):
        """
        Initializes cluster state with given unique node IDs.
        Total node count N = len(node_ids). Quorum threshold is floor(N / 2) + 1.
        """
        self.node_ids: list[str] = list(node_ids)
        self.quorum_threshold: int = len(self.node_ids) // 2 + 1

        # Each node maps key -> (value, version)
        self._stores: dict[str, dict[str, tuple[Any, int]]] = {
            node_id: {} for node_id in self.node_ids
        }

        # Monotonically increasing counter for write versioning
        self._version_counter: int = 0

        # Partition mapping: node_id -> set of reachable node_ids
        self._partitions: dict[str, set[str]] = {}
        self.heal_partition()

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        """
        Divides cluster into isolated network partitions where nodes in group_a
        can only talk to group_a, and group_b only to group_b.
        """
        set_a = set(group_a) & set(self.node_ids)
        set_b = set(group_b) & set(self.node_ids)

        self._partitions = {}
        for node in self.node_ids:
            if node in set_a:
                self._partitions[node] = set_a
            elif node in set_b:
                self._partitions[node] = set_b
            else:
                self._partitions[node] = {node}

    def heal_partition(self) -> None:
        """
        Restores full connectivity so all nodes can communicate,
        synchronizing committed state across all nodes.
        """
        # Identify the latest committed state for every key across all nodes
        latest_state: dict[str, tuple[Any, int]] = {}
        for store in self._stores.values():
            for key, (val, ver) in store.items():
                if key not in latest_state or ver > latest_state[key][1]:
                    latest_state[key] = (val, ver)

        # Synchronize all nodes with the latest state
        for node in self.node_ids:
            self._stores[node] = dict(latest_state)

        # Restore full cluster connectivity
        full_cluster = set(self.node_ids)
        self._partitions = {node: full_cluster for node in self.node_ids}

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        """
        Proposes a write from from_node.
        If from_node belongs to a partition having a STRICT MAJORITY
        (active partition size >= quorum threshold), the write commits,
        updates state in all nodes within that partition, and returns True.
        Otherwise, returns False.
        """
        if from_node not in self.node_ids:
            return False

        active_partition = self._partitions.get(from_node, {from_node})
        if len(active_partition) < self.quorum_threshold:
            return False

        self._version_counter += 1
        entry = (value, self._version_counter)
        for node in active_partition:
            self._stores[node][key] = entry

        return True

    def read_value(self, from_node: str, key: str) -> Any:
        """
        Returns the committed value for key on from_node (or None if not set).
        """
        if from_node not in self.node_ids:
            return None

        node_store = self._stores.get(from_node, {})
        if key in node_store:
            return node_store[key][0]
        return None
