import re
from typing import Tuple


def is_safe_sql_query(query: str) -> tuple[bool, str]:
    """
    Analyzes a SQL query string to detect malicious SQL injection signatures
    while allowing legitimate, modern SQL queries.

    Parameters:
        query (str): The raw or formatted SQL query string to inspect.

    Returns:
        tuple[bool, str]: (True, "SAFE") if the query is legitimate.
                          (False, "<REASON>") if malicious SQL injection signatures are detected.
    """
    if not isinstance(query, str):
        return False, "Invalid input: query must be a string"

    raw_query = query.strip()
    if not raw_query:
        return True, "SAFE"

    # =========================================================================
    # 1. OBFUSCATION & EVASION ATTEMPTS ON RAW INPUT
    # =========================================================================

    # Null byte or encoded null byte injection
    if "\x00" in raw_query or "%00" in raw_query:
        return False, "Obfuscation: Null byte injection detected"

    # MySQL conditional executable comments: e.g., /*!50000SELECT*/, /*!UNION*/
    if re.search(r"/\*!\s*\d*", raw_query, re.IGNORECASE):
        return False, "Obfuscation: MySQL conditional comment execution detected (/*!...*/)"

    # Inline comment evasion splitting tokens / keywords: e.g., UN/**/ION, SEL/**/ECT
    if re.search(r"[a-zA-Z]/\*.*?\*/[a-zA-Z]", raw_query, re.DOTALL):
        return False, "Obfuscation: Inline comment evasion detected (token splitting)"

    # Suspicious block comment placed directly between alphanumeric characters
    if re.search(r"[a-zA-Z0-9_]/\*.*?\*/[a-zA-Z0-9_]", raw_query, re.DOTALL):
        return False, "Obfuscation: Inline comment evasion detected"

    # Unclosed block comment check outside string literals
    temp_no_strings = re.sub(r"'(''|\\.|[^'])*'", "''", raw_query)
    temp_no_strings = re.sub(r'"(""|\\.|[^"])*"', '""', temp_no_strings)
    if "/*" in temp_no_strings:
        idx = 0
        while idx < len(temp_no_strings):
            b_start = temp_no_strings.find("/*", idx)
            if b_start == -1:
                break
            b_end = temp_no_strings.find("*/", b_start + 2)
            if b_end == -1:
                return False, "Obfuscation: Unclosed block comment detected"
            idx = b_end + 2

    # Breakout injection signatures on raw input:
    raw_breakout_patterns = [
        # Starts with quote or quote-delimiter followed by boolean/union/stacked operator
        (r"""^\s*['"]\s*(?:OR|AND|UNION|;|--|#|/\*)\b""", "Boolean/Tautology breakout injection detected"),
        # Starts with identifier/number + quote + boolean/union/comment/stacked
        (r"""^\s*[\w\d]+['"]\s*(?:OR|AND|UNION|;|--|#|/\*)""", "Quote breakout injection detected"),
        # Starts with parentheses breakout: ') OR, ") OR, ')) OR
        (r"""^\s*['"]?\s*\)+\s*(?:OR|AND|UNION)\b""", "Parenthesis breakout injection detected"),
        # Line comment or block comment immediately following a quote outside legitimate string
        (r"""(?:'|")\s*(?:--|#|/\*)""", "Malicious comment injection after quote breakout detected"),
    ]
    for pat, reason in raw_breakout_patterns:
        if re.search(pat, raw_query, re.IGNORECASE):
            return False, reason

    # =========================================================================
    # 2. TOKENIZATION & STRUCTURED PARSING
    # =========================================================================
    tokens = []
    i = 0
    n = len(raw_query)

    while i < n:
        char = raw_query[i]

        # Whitespace normalization
        if char.isspace():
            i += 1
            continue

        # PostgreSQL dollar-quoted string: $$...$$ or $tag$...$tag$
        if char == '$':
            dollar_match = re.match(r"^\$([a-zA-Z0-9_]*)\$", raw_query[i:])
            if dollar_match:
                tag = dollar_match.group(1)
                end_tag = f"${tag}$"
                end_idx = raw_query.find(end_tag, i + len(end_tag))
                if end_idx != -1:
                    str_content = raw_query[i + len(end_tag) : end_idx]
                    tokens.append(('STRING', str_content))
                    i = end_idx + len(end_tag)
                    continue
                else:
                    return False, "Unclosed dollar-quoted string detected"

        # Single-quoted string literal: '...' (with '' and \' escaping)
        if char == "'":
            j = i + 1
            str_parts = []
            closed = False
            while j < n:
                if raw_query[j] == "\\":
                    if j + 1 < n:
                        str_parts.append(raw_query[j:j+2])
                        j += 2
                    else:
                        j += 1
                elif raw_query[j] == "'":
                    if j + 1 < n and raw_query[j+1] == "'":
                        str_parts.append("'")
                        j += 2
                    else:
                        closed = True
                        j += 1
                        break
                else:
                    str_parts.append(raw_query[j])
                    j += 1
            if not closed:
                return False, "Boolean/Tautology injection or syntax error: Unclosed single quote detected"
            tokens.append(('STRING', "".join(str_parts)))
            i = j
            continue

        # Double-quoted identifier or string: "..."
        if char == '"':
            j = i + 1
            ident_parts = []
            closed = False
            while j < n:
                if raw_query[j] == "\\":
                    if j + 1 < n:
                        ident_parts.append(raw_query[j:j+2])
                        j += 2
                    else:
                        j += 1
                elif raw_query[j] == '"':
                    if j + 1 < n and raw_query[j+1] == '"':
                        ident_parts.append('"')
                        j += 2
                    else:
                        closed = True
                        j += 1
                        break
                else:
                    ident_parts.append(raw_query[j])
                    j += 1
            if not closed:
                return False, "Boolean/Tautology injection or syntax error: Unclosed double quote detected"
            tokens.append(('IDENT', "".join(ident_parts)))
            i = j
            continue

        # Block comments /* ... */
        if raw_query[i:i+2] == "/*":
            end_idx = raw_query.find("*/", i + 2)
            if end_idx != -1:
                i = end_idx + 2
                continue
            else:
                return False, "Obfuscation: Unclosed block comment detected"

        # Line comments -- or #
        if raw_query[i:i+2] == "--" or char == "#":
            end_idx = raw_query.find("\n", i)
            comment_body = raw_query[i:end_idx] if end_idx != -1 else raw_query[i:]
            tokens.append(('COMMENT', comment_body))
            if end_idx != -1:
                i = end_idx + 1
            else:
                break
            continue

        # JSON & multi-character operators: ->>, ->, #>>, #>, <=, >=, <>, !=, ||, ::
        if raw_query[i:i+3] in ("->>", "#>>"):
            tokens.append(('OPERATOR', raw_query[i:i+3]))
            i += 3
            continue
        if raw_query[i:i+2] in ("->", "#>", "<=", ">=", "<>", "!=", "||", "::"):
            tokens.append(('OPERATOR', raw_query[i:i+2]))
            i += 2
            continue

        # Single-character operators & punctuation
        if char in "=<>+-*/%!&|^~":
            tokens.append(('OPERATOR', char))
            i += 1
            continue

        if char in "();,[]{}":
            tokens.append(('PUNCT', char))
            i += 1
            continue

        # Numeric constants
        num_match = re.match(r"^\d+(?:\.\d+)?", raw_query[i:])
        if num_match:
            tokens.append(('NUMBER', num_match.group(0)))
            i += len(num_match.group(0))
            continue

        # Keywords / identifiers (including dotted routines like dbms_pipe.receive_message)
        word_match = re.match(r"^[a-zA-Z_][a-zA-Z0-9_]*(?:\.[a-zA-Z_][a-zA-Z0-9_]*)?", raw_query[i:])
        if word_match:
            word = word_match.group(0)
            tokens.append(('KEYWORD', word.upper()))
            i += len(word)
            continue

        tokens.append(('CHAR', char))
        i += 1

    # =========================================================================
    # 3. SEMANTIC & SYNTACTIC SECURITY INSPECTION
    # =========================================================================
    code_tokens = [t for t in tokens if t[0] != 'COMMENT']

    # 3.1 Time-Based Blind Execution Signatures
    time_functions = {
        "PG_SLEEP", "SLEEP", "BENCHMARK", "DBMS_PIPE.RECEIVE_MESSAGE",
        "DBMS_LOCK.SLEEP", "WAITFOR", "PG_SLEEP_FOR", "PG_SLEEP_UNTIL"
    }
    for idx, (ttype, val) in enumerate(code_tokens):
        if ttype == 'KEYWORD':
            if val == "WAITFOR":
                if idx + 1 < len(code_tokens) and code_tokens[idx + 1][1] in ("DELAY", "TIME"):
                    return False, "Time-based blind execution detected: WAITFOR DELAY/TIME"
            elif val in time_functions:
                if idx + 1 < len(code_tokens) and code_tokens[idx + 1][1] == "(":
                    return False, f"Time-based blind execution detected: {val}()"

    # 3.2 UNION-Based Data Exfiltration Signatures
    for idx, (ttype, val) in enumerate(code_tokens):
        if ttype == 'KEYWORD' and val == 'UNION':
            next_idx = idx + 1
            if next_idx < len(code_tokens) and code_tokens[next_idx][1] in ('ALL', 'DISTINCT'):
                next_idx += 1
            if next_idx < len(code_tokens):
                if code_tokens[next_idx][1] == 'SELECT' or code_tokens[next_idx][1] == '(':
                    return False, "UNION-based data exfiltration detected: UNION SELECT"

    # 3.3 Stacked Query Execution Signatures
    dangerous_after_semicolon = {
        "DROP", "DELETE", "TRUNCATE", "ALTER", "CREATE", "EXEC", "EXECUTE",
        "INSERT", "UPDATE", "GRANT", "REVOKE", "SHUTDOWN", "KILL", "CALL",
        "DECLARE", "MERGE", "RENAME", "SELECT", "XP_CMDSHELL"
    }
    for idx, (ttype, val) in enumerate(code_tokens):
        if ttype == 'PUNCT' and val == ';':
            if idx + 1 < len(code_tokens):
                next_tok = code_tokens[idx + 1]
                if next_tok[0] == 'KEYWORD' and next_tok[1] in dangerous_after_semicolon:
                    return False, f"Stacked query execution detected: '; {next_tok[1]}'"
                if next_tok[0] == 'KEYWORD':
                    return False, f"Stacked query execution detected after semicolon: '; {next_tok[1]}'"

    # 3.4 Boolean / Tautology Injection Signatures
    # A. Constant literal comparison: (LITERAL op LITERAL) where LHS == RHS
    clause_starters = {'WHERE', 'OR', 'AND', 'HAVING', 'ON', '('}
    for idx in range(len(code_tokens) - 2):
        tok1 = code_tokens[idx]
        op = code_tokens[idx + 1]
        tok2 = code_tokens[idx + 2]

        # Ensure comparison is in a predicate/filtering clause context
        is_clause_context = (idx == 0) or (code_tokens[idx - 1][1] in clause_starters)

        if op[0] == 'OPERATOR' and op[1] in ('=', '<>', '!=', '<=', '>=', '<', '>'):
            # Comparing identical string literals directly in boolean/filter context
            if tok1[0] == 'STRING' and tok2[0] == 'STRING' and is_clause_context:
                if tok1[1] == tok2[1]:
                    return False, f"Boolean/Tautology injection detected: '{tok1[1]}' {op[1]} '{tok2[1]}'"
            # Comparing identical numeric literals directly in boolean/filter context
            if tok1[0] == 'NUMBER' and tok2[0] == 'NUMBER' and is_clause_context:
                if tok1[1] == tok2[1]:
                    return False, f"Boolean/Tautology injection detected: {tok1[1]} {op[1]} {tok2[1]}"
            # Comparing identical identifiers in boolean clause (e.g. WHERE id = id or OR 1=1)
            if tok1[0] == 'IDENT' and tok2[0] == 'IDENT' and is_clause_context:
                if tok1[1] == tok2[1]:
                    return False, f"Boolean/Tautology injection detected: \"{tok1[1]}\" {op[1]} \"{tok2[1]}\""

    # B. Boolean operators followed by tautological literals
    for idx, (ttype, val) in enumerate(code_tokens):
        if ttype == 'KEYWORD' and val in ('OR', 'AND'):
            if idx + 1 < len(code_tokens):
                next_tok = code_tokens[idx + 1]
                # e.g., OR TRUE
                if next_tok[0] == 'KEYWORD' and next_tok[1] in ('TRUE', '1'):
                    return False, f"Boolean/Tautology injection detected: {val} {next_tok[1]}"
                # e.g., OR NULL IS NULL
                if next_tok[0] == 'KEYWORD' and next_tok[1] == 'NULL':
                    if idx + 3 < len(code_tokens):
                        if code_tokens[idx+2][1] == 'IS' and code_tokens[idx+3][1] == 'NULL':
                            return False, "Boolean/Tautology injection detected: NULL IS NULL"
                # e.g., OR 1 (followed by statement end, comment or parenthesis)
                if next_tok[0] == 'NUMBER' and next_tok[1] == '1':
                    if idx + 2 >= len(code_tokens) or code_tokens[idx+2][1] in (';', ')'):
                        return False, "Boolean/Tautology injection detected: OR 1"

    # C. Standalone injection fragment starting with boolean/union keywords
    if code_tokens:
        first_tok = code_tokens[0]
        if first_tok[0] == 'KEYWORD' and first_tok[1] in ('OR', 'UNION', 'AND'):
            return False, f"Malicious query fragment detected starting with {first_tok[1]}"

    # D. Dangling comments used to truncate queries
    if tokens and tokens[-1][0] == 'COMMENT':
        if len(code_tokens) > 0:
            last_code = code_tokens[-1]
            if last_code[1] in ('=', 'OR', 'AND') or last_code[0] == 'STRING':
                return False, "Comment truncation injection detected at end of query"

    return True, "SAFE"
