    """Prune unused imports and dead top-level private functions from Python source code.

    Preserves module docstrings, class definitions, global variable assignments,
    and public functions while ensuring the returned code is syntactically valid.
    """
    tree = ast.parse(source_code)

    def get_names_in_node(node: ast.AST) -> set[str]:
        names: set[str] = set()
        for child in ast.walk(node):
            if isinstance(child, ast.Name):
                names.add(child.id)
            elif isinstance(child, (ast.Global, ast.Nonlocal)):
                names.update(child.names)
            elif isinstance(child, ast.Assign):
                for target in child.targets:
                    if isinstance(target, ast.Name) and target.id == "__all__":
                        for elt in ast.walk(child.value):
                            if isinstance(elt, ast.Constant) and isinstance(elt.value, str):
                                names.add(elt.value)
            elif isinstance(child, ast.AugAssign):
                if isinstance(child.target, ast.Name) and child.target.id == "__all__":
                    for elt in ast.walk(child.value):
                        if isinstance(elt, ast.Constant) and isinstance(elt.value, str):
                            names.add(elt.value)
        return names

    def get_alias_bound_name(alias: ast.alias, is_from_import: bool) -> str:
        if alias.asname:
            return alias.asname
        if is_from_import:
            return alias.name
        return alias.name.split(".")[0]

    # 1. Separate roots (public functions, classes, global statements) from private functions
    roots: list[ast.stmt] = []
    private_funcs: dict[str, list[ast.stmt]] = {}

    for stmt in tree.body:
        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)) and stmt.name.startswith("_"):
            private_funcs.setdefault(stmt.name, []).append(stmt)
        elif isinstance(stmt, (ast.Import, ast.ImportFrom)):
            pass
        else:
            roots.append(stmt)

    # 2. Collect referenced names starting from root statements
    live_names: set[str] = set()
    for root in roots:
        live_names.update(get_names_in_node(root))

    # 3. Iteratively determine reachable private functions (reachability analysis)
    live_private_func_names: set[str] = set()
    changed = True
    while changed:
        changed = False
        for name, funcs in list(private_funcs.items()):
            if name in live_names and name not in live_private_func_names:
                live_private_func_names.add(name)
                for fn in funcs:
                    live_names.update(get_names_in_node(fn))
                changed = True

    # 4. Collect all referenced names across all retained live code
    live_referenced_names: set[str] = set()
    for root in roots:
        live_referenced_names.update(get_names_in_node(root))
    for name in live_private_func_names:
        for fn in private_funcs[name]:
            live_referenced_names.update(get_names_in_node(fn))

    # 5. Filter top-level statements: prune dead private functions and unused imports
    new_body: list[ast.stmt] = []
    for stmt in tree.body:
        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)) and stmt.name.startswith("_"):
            if stmt.name in live_private_func_names:
                new_body.append(stmt)
        elif isinstance(stmt, ast.Import):
            kept_aliases = [
                alias
                for alias in stmt.names
                if get_alias_bound_name(alias, is_from_import=False) in live_referenced_names
            ]
            if kept_aliases:
                stmt.names = kept_aliases
                new_body.append(stmt)
        elif isinstance(stmt, ast.ImportFrom):
            kept_aliases = [
                alias
                for alias in stmt.names
                if alias.name == "*"
                or get_alias_bound_name(alias, is_from_import=True) in live_referenced_names
            ]
            if kept_aliases:
                stmt.names = kept_aliases
                new_body.append(stmt)
        else:
            new_body.append(stmt)

    tree.body = new_body

    # 6. Prune any unused imports within nested blocks (e.g. if blocks or functions)
    class InnerImportPruner(ast.NodeTransformer):
        def visit_Import(self, node: ast.Import) -> ast.AST | None:
            kept = [
                a
                for a in node.names
                if get_alias_bound_name(a, is_from_import=False) in live_referenced_names
            ]
            if not kept:
                return None
            node.names = kept
            return node

        def visit_ImportFrom(self, node: ast.ImportFrom) -> ast.AST | None:
            kept = [
                a
                for a in node.names
                if a.name == "*"
                or get_alias_bound_name(a, is_from_import=True) in live_referenced_names
            ]
            if not kept:
                return None
            node.names = kept
            return node

        def generic_visit(self, node: ast.AST) -> ast.AST:
            had_body = hasattr(node, "body") and isinstance(node.body, list) and len(node.body) > 0
            had_orelse = hasattr(node, "orelse") and isinstance(node.orelse, list) and len(node.orelse) > 0
            had_finalbody = hasattr(node, "finalbody") and isinstance(node.finalbody, list) and len(node.finalbody) > 0

            super().generic_visit(node)

            if not isinstance(node, ast.Module):
                if had_body and hasattr(node, "body") and len(node.body) == 0:
                    node.body = [ast.Pass()]
                if had_orelse and hasattr(node, "orelse") and len(node.orelse) == 0:
                    node.orelse = [ast.Pass()]
                if had_finalbody and hasattr(node, "finalbody") and len(node.finalbody) == 0:
                    node.finalbody = [ast.Pass()]
            return node

    tree = InnerImportPruner().visit(tree)
    ast.fix_missing_locations(tree)

    result_code = ast.unparse(tree)
    compile(result_code, "<string>", "exec")
    return result_code
