import threading
import time
from collections import deque
from typing import Dict, Optional


class SlidingWindowRateLimiter:
    """Thread-safe sliding window rate limiter implementation."""

    def __init__(self, max_requests: int, window_seconds: float):
        if max_requests <= 0:
            raise ValueError("max_requests must be positive")
        if window_seconds <= 0:
            raise ValueError("window_seconds must be positive")

        self.max_requests = max_requests
        self.window_seconds = float(window_seconds)
        self._lock = threading.Lock()
        self._requests: Dict[str, deque] = {}

    def _get_active_timestamps(self, key: str, current_time: float) -> deque:
        """Helper to clear expired timestamps and return the active request deque for a key.

        Must be called while holding `self._lock`.
        """
        cutoff = current_time - self.window_seconds
        timestamps = self._requests.get(key)

        if timestamps is None:
            timestamps = deque()
            self._requests[key] = timestamps
            return timestamps

        while timestamps and timestamps[0] <= cutoff:
            timestamps.popleft()

        return timestamps

    def allow_request(
        self, key: str, timestamp: Optional[float] = None
    ) -> tuple[bool, float]:
        now = timestamp if timestamp is not None else time.monotonic()

        with self._lock:
            timestamps = self._get_active_timestamps(key, now)
            if len(timestamps) < self.max_requests:
                timestamps.append(now)
                return True, 0.0
            else:
                retry_after = (timestamps[0] + self.window_seconds) - now
                return False, max(0.0, retry_after)

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        now = timestamp if timestamp is not None else time.monotonic()

        with self._lock:
            timestamps = self._get_active_timestamps(key, now)
            return max(0, self.max_requests - len(timestamps))
