import asyncio
import inspect
from typing import Optional, Any, Callable


class AsyncWorkerPool:
    """
    An asynchronous worker pool using standard asyncio.
    Supports priority task execution, concurrency control, and clean shutdown.
    """

    def __init__(self, concurrency: int = 3, max_queue_size: int = 100):
        if concurrency <= 0:
            raise ValueError("concurrency must be greater than 0")
        if max_queue_size < 0:
            raise ValueError("max_queue_size must be >= 0")

        self._concurrency = concurrency
        self._max_queue_size = max_queue_size
        self._queue: asyncio.PriorityQueue = asyncio.PriorityQueue(maxsize=max_queue_size)
        self._workers: list[asyncio.Task] = []
        self._counter: int = 0
        self._started: bool = False
        self._shutting_down: bool = False

    def _spawn_workers(self) -> None:
        if self._started:
            return
        self._started = True
        for i in range(self._concurrency):
            task = asyncio.create_task(self._worker(i), name=f"AsyncWorkerPool-worker-{i}")
            self._workers.append(task)

    async def start(self) -> None:
        """Spawns worker tasks."""
        if self._shutting_down:
            raise RuntimeError("Pool is shutting down")
        self._spawn_workers()

    async def submit(
        self, coro_func: Callable, *args: Any, priority: int = 0, **kwargs: Any
    ) -> asyncio.Future:
        """
        Enqueues a coroutine function coro_func(*args, **kwargs) to be executed by the pool workers.
        Higher priority integer executes before lower priority integers.
        Returns an asyncio.Future that resolves with the result (or exception).
        If pool is shutting down, raises RuntimeError("Pool is shutting down").
        """
        if self._shutting_down:
            raise RuntimeError("Pool is shutting down")

        loop = asyncio.get_running_loop()
        fut = loop.create_future()
        self._counter += 1

        # asyncio.PriorityQueue pops smallest values first. We negate priority (-priority)
        # so higher priority integers are popped first. self._counter breaks ties and preserves FIFO.
        item = (-priority, self._counter, coro_func, args, kwargs, fut)

        try:
            await self._queue.put(item)
        except asyncio.CancelledError:
            if not fut.done():
                fut.cancel()
            raise

        if self._shutting_down:
            if not fut.done():
                fut.cancel()
            raise RuntimeError("Pool is shutting down")

        return fut

    async def _worker(self, worker_id: int) -> None:
        while True:
            try:
                item = await self._queue.get()
            except asyncio.CancelledError:
                break

            neg_prio, count, coro_func, args, kwargs, fut = item

            if fut.cancelled():
                self._queue.task_done()
                continue

            try:
                try:
                    res = coro_func(*args, **kwargs)
                    if inspect.isawaitable(res) or asyncio.iscoroutine(res):
                        res = await res
                    if not fut.done():
                        fut.set_result(res)
                except asyncio.CancelledError as e:
                    if not fut.done():
                        fut.cancel()
                    current_task = asyncio.current_task()
                    is_worker_cancelled = False
                    if current_task is not None:
                        if hasattr(current_task, "cancelling") and current_task.cancelling() > 0:
                            is_worker_cancelled = True
                        elif current_task.cancelled():
                            is_worker_cancelled = True

                    if is_worker_cancelled:
                        raise
                except Exception as exc:
                    if not fut.done():
                        fut.set_exception(exc)
                except BaseException as exc:
                    if not fut.done():
                        fut.set_exception(exc)
                    raise
            finally:
                self._queue.task_done()

    async def shutdown(self, drain: bool = True, timeout: Optional[float] = 5.0) -> None:
        """
        Shuts down the worker pool.
        - If drain=True, waits for all currently enqueued tasks to complete before stopping workers.
        - If drain=False, cancels all queued and currently executing tasks immediately.
        - Respects optional timeout seconds.
        """
        if self._shutting_down:
            return
        self._shutting_down = True

        async def _do_shutdown():
            if drain:
                if not self._started and not self._queue.empty():
                    self._spawn_workers()

                if self._workers:
                    await self._queue.join()
                    for worker in self._workers:
                        worker.cancel()
                    await asyncio.gather(*self._workers, return_exceptions=True)
            else:
                # Cancel all queued tasks that haven't started
                while not self._queue.empty():
                    try:
                        item = self._queue.get_nowait()
                        _, _, _, _, _, fut = item
                        if not fut.done():
                            fut.cancel()
                        self._queue.task_done()
                    except asyncio.QueueEmpty:
                        break

                # Cancel currently executing worker tasks
                for worker in self._workers:
                    worker.cancel()
                if self._workers:
                    await asyncio.gather(*self._workers, return_exceptions=True)

        if timeout is not None and timeout > 0:
            try:
                await asyncio.wait_for(_do_shutdown(), timeout=timeout)
            except asyncio.TimeoutError:
                # Force cleanup of queued items and worker tasks if shutdown times out
                while not self._queue.empty():
                    try:
                        item = self._queue.get_nowait()
                        _, _, _, _, _, fut = item
                        if not fut.done():
                            fut.cancel()
                        self._queue.task_done()
                    except asyncio.QueueEmpty:
                        break
                for worker in self._workers:
                    worker.cancel()
                if self._workers:
                    await asyncio.gather(*self._workers, return_exceptions=True)
                raise
        else:
            await _do_shutdown()
