from typing import Any


class QuorumCluster:
    def __init__(self, node_ids: list[str]) -> None:
        """
        Initializes cluster state with given unique node IDs.
        Total node count N = len(node_ids). Quorum threshold is floor(N / 2) + 1.
        """
        self.node_ids: list[str] = list(node_ids)
        self.N: int = len(self.node_ids)
        self.quorum_threshold: int = (self.N // 2) + 1
        self.partitions: list[set[str]] = [set(self.node_ids)]
        # Map each node_id to its local store: dict[key, tuple[value, version]]
        self.stores: dict[str, dict[str, tuple[Any, int]]] = {
            node_id: {} for node_id in self.node_ids
        }

    def _get_partition(self, node_id: str) -> set[str]:
        """Returns the partition set containing node_id."""
        for partition in self.partitions:
            if node_id in partition:
                return partition
        return set()

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        """
        Divides cluster into isolated network partitions where nodes in group_a
        can only talk to group_a, and group_b only to group_b.
        """
        set_a = set(group_a)
        set_b = set(group_b)
        remaining = set(self.node_ids) - set_a - set_b
        self.partitions = [set_a, set_b] + [{node} for node in remaining]

    def heal_partition(self) -> None:
        """
        Restores full connectivity so all nodes can communicate,
        synchronizing committed state across all nodes.
        """
        self.partitions = [set(self.node_ids)]

        # Collect latest committed (value, version) for each key across the cluster
        latest_state: dict[str, tuple[Any, int]] = {}
        for node_id in self.node_ids:
            for key, (val, ver) in self.stores[node_id].items():
                if key not in latest_state or ver > latest_state[key][1]:
                    latest_state[key] = (val, ver)

        # Synchronize all nodes to the latest committed state
        for node_id in self.node_ids:
            self.stores[node_id] = dict(latest_state)

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        """
        Proposes a write from from_node.
        Commits if from_node belongs to a partition with size >= quorum_threshold.
        Rejects if in a minority partition (< quorum_threshold).
        """
        if from_node not in self.node_ids:
            return False

        part = self._get_partition(from_node)
        if len(part) < self.quorum_threshold:
            return False

        # Find maximum version for the key within the majority partition
        max_ver = 0
        for node in part:
            if key in self.stores[node]:
                ver = self.stores[node][key][1]
                if ver > max_ver:
                    max_ver = ver

        new_ver = max_ver + 1

        # Update state on all nodes in the partition
        for node in part:
            self.stores[node][key] = (value, new_ver)

        return True

    def read_value(self, from_node: str, key: str) -> Any:
        """
        Returns the committed value for key on from_node (or None if not set).
        """
        if from_node in self.stores and key in self.stores[from_node]:
            return self.stores[from_node][key][0]
        return None
