import ast


def extract_exported_names(tree: ast.Module) -> set[str]:
    exported = set()
    for stmt in tree.body:
        target_names = []
        if isinstance(stmt, ast.Assign):
            for t in stmt.targets:
                if isinstance(t, ast.Name):
                    target_names.append(t.id)
        elif isinstance(stmt, (ast.AnnAssign, ast.AugAssign)):
            if isinstance(stmt.target, ast.Name):
                target_names.append(stmt.target.id)
        elif isinstance(stmt, ast.Expr) and isinstance(stmt.value, ast.Call):
            if isinstance(stmt.value.func, ast.Attribute):
                if (
                    isinstance(stmt.value.func.value, ast.Name)
                    and stmt.value.func.value.id == "__all__"
                ):
                    target_names.append("__all__")

        if "__all__" in target_names and stmt.value:
            for node in ast.walk(stmt.value):
                if isinstance(node, ast.Constant) and isinstance(
                    node.value, str
                ):
                    exported.add(node.value)
    return exported


def prune_dead_code_and_imports(source_code: str) -> str:
    """Parses Python source code and prunes unused imports and dead top-level private functions.

    - Removes unused `import` and `from ... import ...` statements or unused imported names.
    - Removes unused top-level private functions (names starting with '_').
    - Preserves module docstrings, class definitions, public functions, and global assignments.
    - Guarantees the returned code compiles cleanly via `compile()`.
    """
    tree = ast.parse(source_code)
    exported = extract_exported_names(tree)

    top_private_funcs = {}
    for stmt in tree.body:
        if isinstance(
            stmt, (ast.FunctionDef, ast.AsyncFunctionDef)
        ) and stmt.name.startswith("_"):
            if stmt.name not in exported:
                top_private_funcs[stmt.name] = stmt

    reachable = set(exported)
    queue = list(exported)

    def collect_from_node(node: ast.AST) -> None:
        for child in ast.walk(node):
            if isinstance(child, ast.Name):
                if child.id not in reachable:
                    reachable.add(child.id)
                    queue.append(child.id)
            elif isinstance(child, ast.Constant) and isinstance(
                child.value, str
            ):
                if child.value not in reachable:
                    reachable.add(child.value)
                    queue.append(child.value)

    # Scans root statements (all module body statements except unexported top-level private functions)
    for stmt in tree.body:
        if isinstance(
            stmt, (ast.FunctionDef, ast.AsyncFunctionDef)
        ) and stmt.name.startswith("_"):
            if stmt.name in exported:
                collect_from_node(stmt)
        else:
            collect_from_node(stmt)

    # BFS traversal to find all symbols reachable from roots
    while queue:
        curr = queue.pop(0)
        if curr in top_private_funcs:
            fn = top_private_funcs[curr]
            collect_from_node(fn)

    # Reconstruct module body by filtering out dead private functions and unused imports
    new_body = []
    for stmt in tree.body:
        if isinstance(
            stmt, (ast.FunctionDef, ast.AsyncFunctionDef)
        ) and stmt.name.startswith("_"):
            if stmt.name not in reachable:
                continue

        elif isinstance(stmt, ast.Import):
            used_aliases = []
            for alias in stmt.names:
                bound = (
                    alias.asname if alias.asname else alias.name.split(".")[0]
                )
                if bound in reachable:
                    used_aliases.append(alias)
            if not used_aliases:
                continue
            stmt.names = used_aliases

        elif isinstance(stmt, ast.ImportFrom):
            if stmt.module == "__future__":
                new_body.append(stmt)
                continue
            used_aliases = []
            for alias in stmt.names:
                if alias.name == "*":
                    used_aliases.append(alias)
                    continue
                bound = alias.asname if alias.asname else alias.name
                if bound in reachable:
                    used_aliases.append(alias)
            if not used_aliases:
                continue
            stmt.names = used_aliases

        new_body.append(stmt)

    tree.body = new_body
    return ast.unparse(tree)
