import collections
import threading
import time
from typing import Any, Optional


class TimeBoundedLRUCache:

    def __init__(self, capacity: int, default_ttl_seconds: float = 60.0):
        if capacity <= 0:
            raise ValueError("Capacity must be greater than 0")
        self.capacity = capacity
        self.default_ttl_seconds = default_ttl_seconds
        self._cache = collections.OrderedDict()
        self._lock = threading.RLock()

    def set(
        self, key: str, value: Any, ttl: Optional[float] = None
    ) -> None:
        with self._lock:
            now = time.time()
            ttl_to_use = (
                ttl if ttl is not None else self.default_ttl_seconds
            )
            expiry_time = now + ttl_to_use

            if key in self._cache:
                self._cache[key] = (value, expiry_time)
                self._cache.move_to_end(key)
            else:
                if len(self._cache) >= self.capacity:
                    # Find the oldest expired item
                    oldest_expired_key = None
                    min_expiry = float("inf")
                    for k, (_, exp) in self._cache.items():
                        if now >= exp:
                            if exp < min_expiry:
                                min_expiry = exp
                                oldest_expired_key = k

                    if oldest_expired_key is not None:
                        del self._cache[oldest_expired_key]
                    else:
                        # Evict least recently used (first item in OrderedDict)
                        lru_key = next(iter(self._cache))
                        del self._cache[lru_key]

                self._cache[key] = (value, expiry_time)

    def get(self, key: str) -> Optional[Any]:
        with self._lock:
            if key not in self._cache:
                return None

            value, expiry_time = self._cache[key]
            now = time.time()
            if now >= expiry_time:
                del self._cache[key]
                return None

            self._cache.move_to_end(key)
            return value

    def delete(self, key: str) -> bool:
        with self._lock:
            if key in self._cache:
                del self._cache[key]
                return True
            return False

    def cleanup_expired(self) -> int:
        with self._lock:
            now = time.time()
            expired_keys = [
                k for k, (_, exp) in self._cache.items() if now >= exp
            ]
            for k in expired_keys:
                del self._cache[k]
            return len(expired_keys)

    def size(self) -> int:
        with self._lock:
            now = time.time()
            return sum(1 for _, exp in self._cache.values() if now < exp)
