import collections
import threading
import time
from typing import Optional


class SlidingWindowRateLimiter:

    def __init__(self, max_requests: int, window_seconds: float):
        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self._lock = threading.Lock()
        self._history = collections.defaultdict(collections.deque)

    def allow_request(
        self, key: str, timestamp: Optional[float] = None
    ) -> tuple[bool, float]:
        if timestamp is None:
            timestamp = time.time()

        with self._lock:
            if self.max_requests <= 0:
                return False, self.window_seconds

            history = self._history[key]
            cutoff = timestamp - self.window_seconds

            # Remove timestamps outside the sliding window
            while history and history[0] <= cutoff:
                history.popleft()

            if len(history) < self.max_requests:
                history.append(timestamp)
                return True, 0.0
            else:
                # The oldest request in the window will expire at history[0] + window_seconds
                oldest_expiry = history[0] + self.window_seconds
                retry_after = oldest_expiry - timestamp
                return False, max(0.0, retry_after)

    def get_remaining(
        self, key: str, timestamp: Optional[float] = None
    ) -> int:
        if timestamp is None:
            timestamp = time.time()

        with self._lock:
            if self.max_requests <= 0:
                return 0

            history = self._history[key]
            cutoff = timestamp - self.window_seconds

            # Remove timestamps outside the sliding window
            while history and history[0] <= cutoff:
                history.popleft()

            remaining = self.max_requests - len(history)
            return max(0, remaining)
