import asyncio
from typing import Optional, Set

class AsyncWorkerPool:
    def __init__(self, concurrency: int = 3, max_queue_size: int = 100):
        self._concurrency: int = concurrency
        self._max_queue_size: int = max_queue_size
        self._queue: asyncio.PriorityQueue = asyncio.PriorityQueue(maxsize=max_queue_size)
        self._workers: list[asyncio.Task] = []
        self._is_shutting_down: bool = False
        self._counter: int = 0
        self._pending_submits: Set[asyncio.Task] = set()

    async def start(self) -> None:
        if self._workers:
            return
        self._is_shutting_down = False
        self._workers = [
            asyncio.create_task(self._worker_loop())
            for _ in range(self._concurrency)
        ]

    async def submit(self, coro_func, *args, priority: int = 0, **kwargs) -> asyncio.Future:
        if self._is_shutting_down:
            raise RuntimeError("Pool is shutting down")

        loop = asyncio.get_running_loop()
        future = loop.create_future()
        self._counter += 1
        count = self._counter

        current_task = asyncio.current_task()
        if current_task:
            self._pending_submits.add(current_task)

        try:
            # We put a tuple: (negative priority, FIFO counter, future, coro_func, args, kwargs)
            # Negative priority ensures higher integers are popped first by the PriorityQueue.
            await self._queue.put((-priority, count, future, coro_func, args, kwargs))
        except asyncio.CancelledError:
            if self._is_shutting_down:
                raise RuntimeError("Pool is shutting down")
            raise
        finally:
            if current_task:
                self._pending_submits.discard(current_task)

        return future

    async def _worker_loop(self) -> None:
        while True:
            try:
                item = await self._queue.get()
            except asyncio.CancelledError:
                break

            neg_priority, count, future, coro_func, args, kwargs = item

            if future.cancelled():
                self._queue.task_done()
                continue

            try:
                coro = coro_func(*args, **kwargs)
                result = await coro
                if not future.done():
                    future.set_result(result)
            except asyncio.CancelledError as ce:
                if not future.done():
                    future.cancel()

                # Check if the worker task itself was cancelled vs the inner coroutine.
                current_task = asyncio.current_task()
                if current_task and hasattr(current_task, "cancelling"):
                    if current_task.cancelling() > 0:
                        raise ce
                else:
                    try:
                        await asyncio.sleep(0)
                    except asyncio.CancelledError:
                        raise ce
            except Exception as e:
                if not future.done():
                    future.set_exception(e)
            finally:
                self._queue.task_done()

    async def shutdown(self, drain: bool = True, timeout: Optional[float] = 5.0) -> None:
        if self._is_shutting_down and not self._workers:
            return

        self._is_shutting_down = True

        # Cancel any pending submits immediately
        for task in list(self._pending_submits):
            if not task.done():
                task.cancel()

        try:
            if timeout is not None:
                await asyncio.wait_for(self._do_shutdown(drain), timeout)
            else:
                await self._do_shutdown(drain)
        except (asyncio.TimeoutError, asyncio.CancelledError) as e:
            await self._force_cancel_all()
            if isinstance(e, asyncio.TimeoutError):
                raise
            else:
                raise

    async def _do_shutdown(self, drain: bool) -> None:
        if drain and self._workers:
            await self._queue.join()
        else:
            # Cancel all queued tasks
            while not self._queue.empty():
                try:
                    item = self._queue.get_nowait()
                    neg_priority, count, future, coro_func, args, kwargs = item
                    if not future.done():
                        future.cancel()
                    self._queue.task_done()
                except asyncio.QueueEmpty:
                    break

        # Stop all workers
        for worker in self._workers:
            if not worker.done():
                worker.cancel()

        if self._workers:
            await asyncio.gather(*self._workers, return_exceptions=True)
            self._workers = []

    async def _force_cancel_all(self) -> None:
        while not self._queue.empty():
            try:
                item = self._queue.get_nowait()
                neg_priority, count, future, coro_func, args, kwargs = item
                if not future.done():
                    future.cancel()
                self._queue.task_done()
            except asyncio.QueueEmpty:
                break

        for worker in self._workers:
            if not worker.done():
                worker.cancel()

        if self._workers:
            await asyncio.gather(*self._workers, return_exceptions=True)
            self._workers = []
