from typing import Any

class QuorumCluster:
    def __init__(self, node_ids: list[str]) -> None:
        self.node_ids = list(node_ids)
        self.n = len(self.node_ids)
        self.quorum_threshold = self.n // 2 + 1
        # Each node maps: key -> (value, version)
        self.states = {node_id: {} for node_id in self.node_ids}
        # Initially, all nodes are in one partition
        self.partitions = [set(self.node_ids)]
        # Global logical clock to order updates
        self.global_version = 0

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        set_a = set(group_a)
        set_b = set(group_b)
        self.partitions = [set_a, set_b]

        # Any nodes not in group_a or group_b are isolated in single-node partitions
        remaining_nodes = set(self.node_ids) - set_a - set_b
        for node in remaining_nodes:
            self.partitions.append({node})

    def heal_partition(self) -> None:
        # 1. Gather the latest committed state for each key across all nodes
        latest_committed = {}
        for node_id in self.node_ids:
            for key, (val, version) in self.states[node_id].items():
                if key not in latest_committed or version > latest_committed[key][1]:
                    latest_committed[key] = (val, version)

        # 2. Update all nodes to match the latest committed state
        for node_id in self.node_ids:
            for key, (val, version) in latest_committed.items():
                self.states[node_id][key] = (val, version)

        # 3. Restore the network connection back to a single partition
        self.partitions = [set(self.node_ids)]

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        # Find the network partition containing the writing node
        active_partition = None
        for partition in self.partitions:
            if from_node in partition:
                active_partition = partition
                break

        if active_partition is None:
            return False

        # Check if the active partition forms a strict majority
        if len(active_partition) >= self.quorum_threshold:
            self.global_version += 1
            # Commit and propagate the write within the active partition
            for node in active_partition:
                self.states[node][key] = (value, self.global_version)
            return True
        else:
            return False

    def read_value(self, from_node: str, key: str) -> Any:
        if from_node not in self.states:
            return None
        if key in self.states[from_node]:
            return self.states[from_node][key][0]
        return None
