import threading

class ResilientConnectionPool:
    def __init__(self, max_connections: int = 5, ping_timeout: float = 1.0):
        self.max_connections = max_connections
        self.ping_timeout = ping_timeout
        self._lock = threading.Lock()

        self._next_id = 1
        self._connections = []
        self._available = []

        for _ in range(max_connections):
            conn = {"id": self._next_id, "alive": True}
            self._next_id += 1
            self._connections.append(conn)
            self._available.append(conn)

    def acquire(self) -> dict:
        with self._lock:
            if not self._available:
                raise RuntimeError("Pool exhausted")
            return self._available.pop(0)

    def release(self, conn: dict) -> None:
        with self._lock:
            if conn not in self._connections:
                return
            if conn not in self._available:
                self._available.append(conn)

    def health_check_and_heal(self) -> int:
        healed_count = 0
        with self._lock:
            for idx, conn in enumerate(self._connections):
                if not conn.get("alive", True):
                    new_conn = {"id": self._next_id, "alive": True}
                    self._next_id += 1

                    self._connections[idx] = new_conn
                    healed_count += 1

                    if conn in self._available:
                        avail_idx = self._available.index(conn)
                        self._available[avail_idx] = new_conn
                    else:
                        self._available.append(new_conn)
        return healed_count

    def close_all(self) -> None:
        with self._lock:
            for conn in self._connections:
                conn["alive"] = False
            self._connections.clear()
            self._available.clear()
