import ast

def find_top_level_functions(tree):
    top_level = []
    def traverse(node):
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            top_level.append(node)
            return
        if isinstance(node, ast.ClassDef):
            return
        for child in ast.iter_child_nodes(node):
            traverse(child)
    traverse(tree)
    return top_level

def get_referenced_names(tree, exclude_node=None):
    referenced = set()
    excluded_nodes = set()
    if exclude_node is not None:
        for n in ast.walk(exclude_node):
            excluded_nodes.add(n)

    aug_assign_targets = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.AugAssign):
            if isinstance(node.target, ast.Name):
                aug_assign_targets.add(node.target)

    for node in ast.walk(tree):
        if node in excluded_nodes:
            continue
        if isinstance(node, ast.Name):
            if isinstance(node.ctx, (ast.Load, ast.Del)) or node in aug_assign_targets:
                referenced.add(node.id)
    return referenced

class Pruner(ast.NodeTransformer):
    def __init__(self, dead_functions, dead_imports, partial_imports):
        self.dead_functions = dead_functions
        self.dead_imports = dead_imports
        self.partial_imports = partial_imports

    def visit_FunctionDef(self, node):
        if node in self.dead_functions:
            return None
        self.generic_visit(node)
        return node

    def visit_AsyncFunctionDef(self, node):
        if node in self.dead_functions:
            return None
        self.generic_visit(node)
        return node

    def visit_Import(self, node):
        if node in self.dead_imports:
            return None
        if node in self.partial_imports:
            node.names = self.partial_imports[node]
        return node

    def visit_ImportFrom(self, node):
        if node in self.dead_imports:
            return None
        if node in self.partial_imports:
            node.names = self.partial_imports[node]
        return node

def fix_empty_bodies(node):
    for n in ast.walk(node):
        if isinstance(n, ast.Module):
            continue
        if hasattr(n, 'body'):
            val = getattr(n, 'body')
            if isinstance(val, list) and len(val) == 0:
                n.body = [ast.Pass()]
        is_try = isinstance(n, ast.Try)
        if not is_try and hasattr(ast, 'TryStar') and isinstance(n, getattr(ast, 'TryStar')):
            is_try = True
        if is_try:
            handlers = getattr(n, 'handlers', [])
            finalbody = getattr(n, 'finalbody', [])
            if len(handlers) == 0 and len(finalbody) == 0:
                n.finalbody = [ast.Pass()]

def prune_dead_code_and_imports(source_code: str) -> str:
    current_code = source_code
    while True:
        tree = ast.parse(current_code)

        referenced_globally = get_referenced_names(tree)
        dead_functions = set()
        dead_imports = set()
        partial_imports = {}

        # Check top-level functions
        top_level_funcs = find_top_level_functions(tree)
        for func in top_level_funcs:
            if func.name.startswith('_'):
                referenced_outside = get_referenced_names(tree, exclude_node=func)
                if func.name not in referenced_outside:
                    dead_functions.add(func)

        # Check all imports
        for node in ast.walk(tree):
            if isinstance(node, (ast.Import, ast.ImportFrom)):
                kept_aliases = []
                for alias in node.names:
                    if alias.name == '*':
                        kept_aliases.append(alias)
                        continue

                    if isinstance(node, ast.Import):
                        bound_name = alias.asname if alias.asname is not None else alias.name.split('.')[0]
                    else:
                        bound_name = alias.asname if alias.asname is not None else alias.name

                    if bound_name in referenced_globally:
                        kept_aliases.append(alias)

                if not kept_aliases:
                    dead_imports.add(node)
                elif len(kept_aliases) < len(node.names):
                    partial_imports[node] = kept_aliases

        if not dead_functions and not dead_imports and not partial_imports:
            break

        pruner = Pruner(dead_functions, dead_imports, partial_imports)
        pruned_tree = pruner.visit(tree)
        fix_empty_bodies(pruned_tree)
        ast.fix_missing_locations(pruned_tree)
        current_code = ast.unparse(pruned_tree)

    return current_code
