import time
import threading
from collections import OrderedDict
from typing import Any, Optional

class TimeBoundedLRUCache:
    def __init__(self, capacity: int, default_ttl_seconds: float = 60.0):
        self.capacity = capacity
        self.default_ttl_seconds = default_ttl_seconds
        self.cache: OrderedDict[str, tuple[Any, float]] = OrderedDict()
        self.lock = threading.RLock()

    def set(self, key: str, value: Any, ttl: Optional[float] = None) -> None:
        with self.lock:
            if self.capacity <= 0:
                return

            ttl_to_use = ttl if ttl is not None else self.default_ttl_seconds
            expiry = time.time() + ttl_to_use

            if key in self.cache:
                del self.cache[key]
            elif len(self.cache) >= self.capacity:
                now = time.time()
                expired_items = [(k, exp) for k, (_, exp) in self.cache.items() if now >= exp]
                if expired_items:
                    # Evict the oldest expired item
                    oldest_expired_key = min(expired_items, key=lambda x: x[1])[0]
                    del self.cache[oldest_expired_key]
                else:
                    # Evict the least recently used non-expired item
                    self.cache.popitem(last=False)

            self.cache[key] = (value, expiry)

    def get(self, key: str) -> Optional[Any]:
        with self.lock:
            if key in self.cache:
                value, expiry = self.cache[key]
                if time.time() >= expiry:
                    del self.cache[key]
                    return None

                # Update LRU recency
                self.cache.move_to_end(key)
                return value
            return None

    def delete(self, key: str) -> bool:
        with self.lock:
            if key in self.cache:
                del self.cache[key]
                return True
            return False

    def cleanup_expired(self) -> int:
        with self.lock:
            now = time.time()
            keys_to_delete = [k for k, (_, exp) in self.cache.items() if now >= exp]
            for k in keys_to_delete:
                del self.cache[k]
            return len(keys_to_delete)

    def size(self) -> int:
        with self.lock:
            now = time.time()
            return sum(1 for _, exp in self.cache.values() if now < exp)
