    pass


class DependencyResolver:
    def resolve(self, dependencies: dict[str, list[str]]) -> list[list[str]]:
        # Find all unique tasks from both keys and values
        all_nodes = set(dependencies.keys())
        for deps in dependencies.values():
            all_nodes.update(deps)

        in_degree = {node: 0 for node in all_nodes}
        adj_list = {node: [] for node in all_nodes}

        # Build the graph and calculate in-degrees
        for node, deps in dependencies.items():
            # Use a set to prevent double counting if a dependency is listed multiple times
            for dep in set(deps):
                adj_list[dep].append(node)
                in_degree[node] += 1

        result = []
        # Stage 0: Tasks with no dependencies
        queue = [node for node in all_nodes if in_degree[node] == 0]
        processed_count = 0

        while queue:
            # Sort the tasks within the current stage alphabetically
            queue.sort()
            result.append(queue)
            processed_count += len(queue)

            next_queue = []
            for node in queue:
                for dependent in adj_list[node]:
                    in_degree[dependent] -= 1
                    if in_degree[dependent] == 0:
                        next_queue.append(dependent)

            queue = next_queue

        # If we couldn't process all nodes, there is a cycle
        if processed_count < len(all_nodes):
            raise CircularDependencyError("Circular dependency detected among tasks.")

        return result
