import time
import threading
from collections import deque
from typing import Optional, Dict, Tuple

class SlidingWindowRateLimiter:
    def __init__(self, max_requests: int, window_seconds: float):
        if max_requests <= 0:
            raise ValueError("max_requests must be greater than 0")
        if window_seconds <= 0.0:
            raise ValueError("window_seconds must be greater than 0.0")

        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self.history: Dict[str, deque] = {}
        self.lock = threading.Lock()

    def _cleanup(self, key: str, current_time: float) -> None:
        """Removes timestamps that are outside the current sliding window."""
        if key not in self.history:
            return

        timestamps = self.history[key]
        cutoff = current_time - self.window_seconds

        while timestamps and timestamps[0] <= cutoff:
            timestamps.popleft()

        if not timestamps:
            del self.history[key]

    def allow_request(self, key: str, timestamp: Optional[float] = None) -> Tuple[bool, float]:
        if timestamp is None:
            timestamp = time.time()

        with self.lock:
            self._cleanup(key, timestamp)

            timestamps = self.history.get(key)
            if timestamps is None:
                timestamps = deque()
                self.history[key] = timestamps

            if len(timestamps) < self.max_requests:
                timestamps.append(timestamp)
                return True, 0.0
            else:
                # The next slot will open up when the oldest request falls out of the window
                retry_after = (timestamps[0] + self.window_seconds) - timestamp
                return False, max(0.0, float(retry_after))

    def get_remaining(self, key: str, timestamp: Optional[float] = None) -> int:
        if timestamp is None:
            timestamp = time.time()

        with self.lock:
            self._cleanup(key, timestamp)

            if key not in self.history:
                return self.max_requests

            return self.max_requests - len(self.history[key])
