import asyncio
import itertools
from typing import Optional

class AsyncWorkerPool:
    def __init__(self, concurrency: int = 3, max_queue_size: int = 100):
        self.concurrency = concurrency
        self.max_queue_size = max_queue_size
        self._queue = asyncio.PriorityQueue(maxsize=max_queue_size)
        self._workers = []
        self._is_shutting_down = False
        self._counter = itertools.count()

    async def submit(self, coro_func, *args, priority: int = 0, **kwargs) -> asyncio.Future:
        if self._is_shutting_down:
            raise RuntimeError("Pool is shutting down")

        loop = asyncio.get_running_loop()
        future = loop.create_future()

        # PriorityQueue sorts lowest values first.
        # Negate priority so higher priority executes before lower priority.
        item = (-priority, next(self._counter), coro_func, args, kwargs, future)
        await self._queue.put(item)

        return future

    async def start(self) -> None:
        if self._workers:
            return
        self._is_shutting_down = False
        for _ in range(self.concurrency):
            task = asyncio.create_task(self._worker_loop())
            self._workers.append(task)

    async def _worker_loop(self) -> None:
        worker_task = asyncio.current_task()
        while True:
            try:
                item = await self._queue.get()
            except asyncio.CancelledError:
                break

            priority, counter, coro_func, args, kwargs, future = item

            if future.cancelled():
                self._queue.task_done()
                continue

            is_worker_cancelled = False
            try:
                result = await coro_func(*args, **kwargs)
                if not future.done():
                    future.set_result(result)
            except asyncio.CancelledError:
                if not future.done():
                    future.cancel()
                if worker_task is not None and worker_task.cancelled():
                    is_worker_cancelled = True
            except Exception as e:
                if not future.done():
                    future.set_exception(e)
            finally:
                self._queue.task_done()

            if is_worker_cancelled:
                break

    async def shutdown(self, drain: bool = True, timeout: Optional[float] = 5.0) -> None:
        self._is_shutting_down = True

        async def _drain() -> None:
            await self._queue.join()

        if drain:
            try:
                if timeout is not None:
                    await asyncio.wait_for(_drain(), timeout=timeout)
                else:
                    await _drain()
            except asyncio.TimeoutError:
                pass

        # Cancel all running workers (this will raise CancelledError in running coroutines)
        for worker in self._workers:
            worker.cancel()

        # Wait for workers to gracefully exit
        if self._workers:
            await asyncio.gather(*self._workers, return_exceptions=True)
        self._workers.clear()

        # Empty the queue and cancel any pending futures that didn't run
        while not self._queue.empty():
            try:
                item = self._queue.get_nowait()
                priority, counter, coro_func, args, kwargs, future = item
                if not future.done():
                    future.cancel()
                self._queue.task_done()
            except asyncio.QueueEmpty:
                break
