from typing import Any

class QuorumCluster:
    def __init__(self, node_ids: list[str]):
        self.node_ids = node_ids
        self.quorum_threshold = (len(node_ids) // 2) + 1

        # Track the key-value state and version for each node
        self.node_states = {node_id: {} for node_id in node_ids}
        self.node_versions = {node_id: 0 for node_id in node_ids}

        # Initially, all nodes are in a single partition
        self.partitions = [set(node_ids)]

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        self.partitions = [set(group_a), set(group_b)]

    def heal_partition(self) -> None:
        highest_version = -1
        best_state = None

        # Find the state of the node that belongs to the most advanced partition
        for node in self.node_ids:
            if self.node_versions[node] > highest_version:
                highest_version = self.node_versions[node]
                best_state = self.node_states[node]

        # Sync the most advanced state to all nodes
        if best_state is not None:
            for node in self.node_ids:
                self.node_states[node] = dict(best_state)
                self.node_versions[node] = highest_version

        # Restore full connectivity
        self.partitions = [set(self.node_ids)]

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        node_partition = None
        for p in self.partitions:
            if from_node in p:
                node_partition = p
                break

        # Reject write if node is isolated or in a minority partition
        if node_partition is None or len(node_partition) < self.quorum_threshold:
            return False

        # Determine new version for this state transition
        max_version = max(self.node_versions[n] for n in node_partition)
        new_version = max_version + 1

        # Commit write to all nodes in the majority partition
        for node in node_partition:
            self.node_states[node][key] = value
            self.node_versions[node] = new_version

        return True

    def read_value(self, from_node: str, key: str) -> Any:
        return self.node_states.get(from_node, {}).get(key, None)
