Here is the implementation of the `prune_dead_code_and_imports` function using Python's `ast` module. 

It correctly handles the transitive nature of dead code (e.g., if a private function is only referenced by another dead private function, both will be removed). It also correctly determines the "name brought into scope" for both standard imports and `from`-imports, including aliases, and cascades to inner scopes (like pruning unused imports inside functions). 

```python
import ast

def prune_dead_code_and_imports(source_code: str) -> str:
    tree = ast.parse(source_code)

    def get_referenced_names(node):
        """Collects all names loaded/referenced within a given AST node."""
        names = set()
        for child in ast.walk(node):
            if isinstance(child, ast.Name) and isinstance(child.ctx, ast.Load):
                names.add(child.id)
            elif isinstance(child, (ast.Global, ast.Nonlocal)):
                for name in child.names:
                    names.add(name)
            # Catch references in __all__ definitions, docstrings, or type hints
            elif isinstance(child, ast.Constant) and isinstance(child.value, str):
                names.add(child.value)
            # Fallback for Python < 3.8
            elif type(child).__name__ == 'Str':
                names.add(getattr(child, 's', ''))
        return names

    # 1. Separate top-level statements into keep candidates and prune candidates.
    # Keep candidates include public functions, classes, globals, and imports.
    keep_candidates = []
    prune_candidates = {}

    for stmt in tree.body:
        if isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)) and stmt.name.startswith('_'):
            if stmt.name not in prune_candidates:
                prune_candidates[stmt.name] = []
            prune_candidates[stmt.name].append(stmt)
        else:
            keep_candidates.append(stmt)

    # 2. Iteratively resolve references to handle transitive dependencies.
    used_names = set()
    for stmt in keep_candidates:
        used_names.update(get_referenced_names(stmt))

    changed = True
    while changed:
        changed = False
        names_to_remove = []
        for name, nodes in prune_candidates.items():
            if name in used_names:
                # This private function is referenced; upgrade it to a keep candidate
                for node in nodes:
                    keep_candidates.append(node)
                    used_names.update(get_referenced_names(node))
                names_to_remove.append(name)
                changed = True

        for name in names_to_remove:
            del prune_candidates[name]

    # 3. Filter out the definitively dead private functions from the module body.
    tree.body = [
        stmt for stmt in tree.body 
        if not (isinstance(stmt, (ast.FunctionDef, ast.AsyncFunctionDef)) 
                and stmt.name.startswith('_') 
                and stmt.name not in used_names)
    ]

    # 4. Traverse the remaining tree to prune unused imports (both top-level and inner).
    class ImportPruner(ast.NodeTransformer):
        def visit_Import(self, node):
            new_names = []
            for alias in node.names:
                # `import os.path` brings `os` into scope. `import math as m` brings `m`.
                name_in_scope = alias.asname or alias.name.split('.')[0]
                if name_in_scope in used_names:
                    new_names.append(alias)
            if not new_names:
                return None
            node.names = new_names
            return node

        def visit_ImportFrom(self, node):
            new_names = []
            for alias in node.names:
                name_in_scope = alias.asname or alias.name
                if name_in_scope in used_names or name_in_scope == '*':
                    new_names.append(alias)
            if not new_names:
                return None
            node.names = new_names
            return node

    tree = ImportPruner().visit(tree)
    ast.fix_missing_locations(tree)

    # Generate the finalized code. 
    # (Requires Python >= 3.9, which introduced `ast.unparse`)
    return ast.unparse(tree)
```

