class CircularDependencyError(Exception):
    pass


class DependencyResolver:
    def resolve(self, dependencies: dict[str, list[str]]) -> list[list[str]]:
        tasks = set(dependencies)
        for required_tasks in dependencies.values():
            tasks.update(required_tasks)

        remaining = {
            task: set(dependencies.get(task, []))
            for task in tasks
        }

        stages = []
        while remaining:
            ready = sorted(
                task for task, requirements in remaining.items()
                if not requirements
            )

            if not ready:
                raise CircularDependencyError("Circular dependency detected")

            stages.append(ready)

            for task in ready:
                del remaining[task]

            completed = set(ready)
            for requirements in remaining.values():
                requirements.difference_update(completed)

        return stages
