import asyncio
import itertools
from typing import Any, Awaitable, Callable, Optional


class AsyncWorkerPool:
    def __init__(self, concurrency: int = 3, max_queue_size: int = 100):
        if concurrency < 1:
            raise ValueError("concurrency must be at least 1")
        if max_queue_size < 1:
            raise ValueError("max_queue_size must be at least 1")

        self._concurrency = concurrency
        self._queue: asyncio.PriorityQueue = asyncio.PriorityQueue(
            maxsize=max_queue_size
        )
        self._sequence = itertools.count()
        self._workers: list[asyncio.Task] = []
        self._running_tasks: set[asyncio.Task] = set()
        self._started = False
        self._shutting_down = False
        self._shutdown_complete = False
        self._lifecycle_lock = asyncio.Lock()

    async def start(self) -> None:
        async with self._lifecycle_lock:
            if self._shutting_down:
                raise RuntimeError("Pool is shutting down")

            if self._started:
                return

            self._started = True
            self._workers = [
                asyncio.create_task(self._worker(), name=f"async-worker-{index}")
                for index in range(self._concurrency)
            ]

    async def submit(
        self,
        coro_func: Callable[..., Awaitable[Any]],
        *args: Any,
        priority: int = 0,
        **kwargs: Any,
    ) -> asyncio.Future:
        async with self._lifecycle_lock:
            if self._shutting_down:
                raise RuntimeError("Pool is shutting down")

            if not self._started:
                self._started = True
                self._workers = [
                    asyncio.create_task(
                        self._worker(), name=f"async-worker-{index}"
                    )
                    for index in range(self._concurrency)
                ]

            future = asyncio.get_running_loop().create_future()
            sequence = next(self._sequence)

        await self._queue.put(
            (-priority, sequence, (coro_func, args, kwargs, future))
        )
        return future

    async def shutdown(
        self,
        drain: bool = True,
        timeout: Optional[float] = 5.0,
    ) -> None:
        async with self._lifecycle_lock:
            if self._shutdown_complete:
                return

            self._shutting_down = True

            if not self._started:
                self._shutdown_complete = True
                return

            async def stop() -> None:
                if drain:
                    await self._queue.join()
                    for _ in self._workers:
                        await self._queue.put((float("inf"), next(self._sequence), None))
                else:
                    while True:
                        try:
                            _, _, item = self._queue.get_nowait()
                        except asyncio.QueueEmpty:
                            break

                        try:
                            if item is not None:
                                _, _, _, future = item
                                if not future.done():
                                    future.cancel()
                        finally:
                            self._queue.task_done()

                    for task in list(self._running_tasks):
                        task.cancel()

                    for worker in self._workers:
                        worker.cancel()

                await asyncio.gather(*self._workers, return_exceptions=True)

            try:
                if timeout is None:
                    await stop()
                else:
                    await asyncio.wait_for(stop(), timeout=timeout)
            except asyncio.TimeoutError:
                for task in list(self._running_tasks):
                    task.cancel()
                for worker in self._workers:
                    worker.cancel()
                await asyncio.gather(*self._workers, return_exceptions=True)
                raise
            finally:
                self._shutdown_complete = True

    async def _worker(self) -> None:
        while True:
            _, _, item = await self._queue.get()

            try:
                if item is None:
                    return

                coro_func, args, kwargs, future = item

                if future.cancelled():
                    continue

                try:
                    task = asyncio.create_task(coro_func(*args, **kwargs))
                    self._running_tasks.add(task)

                    try:
                        result = await task
                    finally:
                        self._running_tasks.discard(task)

                    if not future.done():
                        future.set_result(result)

                except asyncio.CancelledError:
                    if not future.done():
                        future.cancel()
                    raise
                except Exception as exc:
                    if not future.done():
                        future.set_exception(exc)

            finally:
                self._queue.task_done()
