from typing import Any


class QuorumCluster:
    def __init__(self, node_ids: list[str]):
        if not node_ids or len(node_ids) != len(set(node_ids)):
            raise ValueError("node_ids must be non-empty and unique")

        self.node_ids = set(node_ids)
        self.node_count = len(node_ids)
        self.quorum_threshold = self.node_count // 2 + 1

        self._committed_state: dict[str, Any] = {}
        self._node_states: dict[str, dict[str, Any]] = {
            node_id: {} for node_id in node_ids
        }
        self._partitions: dict[str, set[str]] = {
            node_id: self.node_ids.copy() for node_id in node_ids
        }

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        group_a_set = set(group_a)
        group_b_set = set(group_b)

        if (
            len(group_a) != len(group_a_set)
            or len(group_b) != len(group_b_set)
            or group_a_set & group_b_set
            or group_a_set | group_b_set != self.node_ids
        ):
            raise ValueError(
                "Partitions must be disjoint, contain no duplicates, "
                "and include every cluster node exactly once"
            )

        for node_id in group_a_set:
            self._partitions[node_id] = group_a_set.copy()
        for node_id in group_b_set:
            self._partitions[node_id] = group_b_set.copy()

    def heal_partition(self) -> None:
        for node_id in self.node_ids:
            self._partitions[node_id] = self.node_ids.copy()
            self._node_states[node_id] = self._committed_state.copy()

    def propose_write(self, from_node: str, key: str, value: Any) -> bool:
        if from_node not in self.node_ids:
            raise ValueError(f"Unknown node: {from_node}")

        active_partition = self._partitions[from_node]
        if len(active_partition) < self.quorum_threshold:
            return False

        self._committed_state[key] = value
        for node_id in active_partition:
            self._node_states[node_id][key] = value

        return True

    def read_value(self, from_node: str, key: str) -> Any:
        if from_node not in self.node_ids:
            raise ValueError(f"Unknown node: {from_node}")

        return self._node_states[from_node].get(key)
