import struct
import zlib


class BinaryFrameParser:
    MAGIC = b"SX"
    _HEADER_SIZE = 8  # magic (2) + type (2) + payload length (4)
    _CHECKSUM_SIZE = 4

    def __init__(self) -> None:
        self._buffer = bytearray()

    def feed(self, data: bytes) -> list[tuple[int, bytes]]:
        self._buffer.extend(data)
        packets: list[tuple[int, bytes]] = []

        while True:
            magic_index = self._buffer.find(self.MAGIC)

            if magic_index < 0:
                if self._buffer.endswith(self.MAGIC[:1]):
                    self._buffer[:] = self.MAGIC[:1]
                else:
                    self._buffer.clear()
                break

            if magic_index > 0:
                del self._buffer[:magic_index]

            if len(self._buffer) < self._HEADER_SIZE:
                break

            msg_type = struct.unpack_from(">H", self._buffer, 2)[0]
            payload_length = struct.unpack_from(">I", self._buffer, 4)[0]
            frame_size = self._HEADER_SIZE + payload_length + self._CHECKSUM_SIZE

            if len(self._buffer) < frame_size:
                break

            payload_end = self._HEADER_SIZE + payload_length
            payload = bytes(self._buffer[self._HEADER_SIZE:payload_end])
            expected_crc = struct.unpack_from(">I", self._buffer, payload_end)[0]
            actual_crc = zlib.crc32(self._buffer[2:payload_end]) & 0xFFFFFFFF

            if actual_crc == expected_crc:
                packets.append((msg_type, payload))
                del self._buffer[:frame_size]
            else:
                del self._buffer[:1]

        return packets
