import base64
import hashlib
import hmac
import json
import time


def verify_jwt(
    token: str,
    secret_key: str,
    allowed_algs: list[str] = ["HS256"],
) -> dict:
    def decode_base64url(segment: str) -> bytes:
        try:
            raw = segment.encode("ascii")
            if len(raw) % 4 == 1:
                raise ValueError("Invalid Base64 URL encoding")
            padded = raw + b"=" * (-len(raw) % 4)
            return base64.b64decode(padded, altchars=b"-_", validate=True)
        except (UnicodeEncodeError, ValueError) as exc:
            raise ValueError("Invalid Base64 URL encoding") from exc

    parts = token.split(".")
    if len(parts) != 3:
        raise ValueError("Invalid JWT format")

    try:
        header = json.loads(decode_base64url(parts[0]))
        payload = json.loads(decode_base64url(parts[1]))
    except (json.JSONDecodeError, UnicodeDecodeError) as exc:
        raise ValueError("Invalid JWT JSON") from exc

    if not isinstance(header, dict) or not isinstance(payload, dict):
        raise ValueError("Invalid JWT content")

    alg = header.get("alg")
    if not isinstance(alg, str) or alg not in allowed_algs:
        raise ValueError("Unapproved JWT algorithm")

    # This verifier implements HS256 only.
    if alg != "HS256":
        raise ValueError("Unsupported JWT algorithm")

    if "exp" in payload:
        exp = payload["exp"]
        if isinstance(exp, bool) or not isinstance(exp, (int, float)):
            raise ValueError("Invalid expiration claim")
        if exp <= time.time():
            raise ValueError("Token expired")

    signature = decode_base64url(parts[2])
    signing_input = f"{parts[0]}.{parts[1]}".encode("ascii")
    expected_sig = hmac.new(
        secret_key.encode("utf-8"),
        signing_input,
        hashlib.sha256,
    ).digest()

    if not hmac.compare_digest(signature, expected_sig):
        raise ValueError("Invalid signature")

    return payload
