def parse_markdown_links(text: str) -> list[dict[str, str]]:
    """Extract valid [title](http(s)://url) links in linear time."""
    results = []
    i = 0
    length = len(text)

    while i < length:
        start = text.find("[", i)
        if start == -1:
            break

        # Parse a non-empty title: ASCII letters, digits, spaces, underscores.
        title_start = start + 1
        j = title_start
        while j < length:
            char = text[j]
            if char.isascii() and (char.isalnum() or char in " _"):
                j += 1
            else:
                break

        if j == title_start or j >= length:
            i = j if j < length else length
            continue

        if text[j] != "]" or j + 1 >= length or text[j + 1] != "(":
            i = j + 1
            continue

        url_start = j + 2
        if text.startswith("https://", url_start):
            url_body_start = url_start + len("https://")
        elif text.startswith("http://", url_start):
            url_body_start = url_start + len("http://")
        else:
            i = j + 1
            continue

        # A URL must contain at least one character after its scheme.
        k = url_body_start
        while k < length and not text[k].isspace() and text[k] != ")":
            k += 1

        if k > url_body_start and k < length and text[k] == ")":
            results.append({
                "title": text[title_start:j],
                "url": text[url_start:k],
            })
            i = k + 1
        else:
            i = k + 1

    return results
