def is_safe_sql_query(query: str) -> tuple[bool, str]:
    import re

    if not isinstance(query, str) or not query.strip():
        return False, "INVALID_INPUT"

    code: list[str] = []
    strings: list[str] = []
    obfuscation_detected = False
    i = 0
    length = len(query)

    def add_string(value: str) -> None:
        strings.append(value)
        code.append(f" __str{len(strings) - 1}__ ")

    while i < length:
        char = query[i]

        # Single-quoted SQL string literal.
        if char == "'":
            start = i
            i += 1
            value: list[str] = []
            closed = False

            while i < length:
                if query[i] == "'" and i + 1 < length and query[i + 1] == "'":
                    value.append("'")
                    i += 2
                elif query[i] == "'":
                    i += 1
                    closed = True
                    break
                elif query[i] == "\\" and i + 1 < length:
                    value.append(query[i + 1])
                    i += 2
                else:
                    value.append(query[i])
                    i += 1

            if not closed:
                if "--" in query[start:]:
                    return False, "BOOLEAN_TAUTOLOGY"
                return False, "MALFORMED_QUERY"

            add_string("".join(value))
            continue

        # Double-quoted identifier/string, depending on SQL dialect.
        if char == '"':
            start = i
            i += 1
            closed = False

            while i < length:
                if query[i] == '"' and i + 1 < length and query[i + 1] == '"':
                    i += 2
                elif query[i] == '"':
                    i += 1
                    closed = True
                    break
                else:
                    i += 1

            if not closed:
                if "--" in query[start:]:
                    return False, "BOOLEAN_TAUTOLOGY"
                return False, "MALFORMED_QUERY"

            code.append(" ")
            continue

        # Backtick-quoted identifier.
        if char == "`":
            i += 1
            while i < length:
                if query[i] == "`" and i + 1 < length and query[i + 1] == "`":
                    i += 2
                elif query[i] == "`":
                    i += 1
                    break
                else:
                    i += 1
            else:
                return False, "MALFORMED_QUERY"
            code.append(" ")
            continue

        # SQL Server bracket-quoted identifier.
        if char == "[":
            i += 1
            while i < length:
                if query[i] == "]" and i + 1 < length and query[i + 1] == "]":
                    i += 2
                elif query[i] == "]":
                    i += 1
                    break
                else:
                    i += 1
            else:
                return False, "MALFORMED_QUERY"
            code.append(" ")
            continue

        # PostgreSQL dollar-quoted string.
        if char == "$":
            dollar_match = re.match(r"\$[A-Za-z_][A-Za-z0-9_]*\$|\$\$", query[i:])
            if dollar_match:
                delimiter = dollar_match.group(0)
                end = query.find(delimiter, i + len(delimiter))
                if end == -1:
                    return False, "MALFORMED_QUERY"
                add_string(query[i + len(delimiter):end])
                i = end + len(delimiter)
                continue

        # Line comments.
        if query.startswith("--", i) or char == "#":
            newline = query.find("\n", i)
            i = length if newline == -1 else newline + 1
            code.append(" ")
            continue

        # Block comments and MySQL executable comments.
        if query.startswith("/*", i):
            end = query.find("*/", i + 2)
            if end == -1:
                return False, "OBFUSCATION"

            comment = query[i:end + 2]
            if comment.startswith("/*!"):
                return False, "OBFUSCATION"

            before = query[max(0, i - 12):i]
            after = query[end + 2:min(length, end + 14)]
            left = re.search(r"([A-Za-z_]+)$", before)
            right = re.match(r"([A-Za-z_]+)", after)

            if left and right:
                joined = (left.group(1) + right.group(1)).lower()
                if joined in {
                    "union", "select", "drop", "delete", "exec", "execute",
                    "pg_sleep", "benchmark", "waitfor", "delay",
                }:
                    obfuscation_detected = True

            i = end + 2
            code.append(" ")
            continue

        code.append(char)
        i += 1

    if obfuscation_detected:
        return False, "OBFUSCATION"

    normalized = " ".join("".join(code).lower().split())
    tokens = re.findall(
        r"__str\d+__|[a-z_][a-z0-9_$]*|\d+(?:\.\d+)?|->>|->|<=|>=|<>|!=|:=|[=;(),]",
        normalized,
    )

    # Stacked destructive/execution queries.
    dangerous_stacked_commands = {
        "drop", "delete", "exec", "execute", "insert", "update",
        "alter", "truncate", "grant", "revoke", "call",
    }
    for index, token in enumerate(tokens):
        if token == ";":
            next_tokens = tokens[index + 1:]
            if next_tokens and next_tokens[0] in dangerous_stacked_commands:
                return False, "STACKED_QUERY"

    # UNION-based data exfiltration.
    for index, token in enumerate(tokens):
        if token == "union":
            next_token = tokens[index + 1] if index + 1 < len(tokens) else ""
            following = tokens[index + 2] if index + 2 < len(tokens) else ""
            if next_token == "select" or (next_token == "all" and following == "select"):
                return False, "UNION_EXFILTRATION"

    # Time-based blind execution.
    if (
        re.search(r"\bpg_sleep\s*\(", normalized)
        or re.search(r"\bbenchmark\s*\(", normalized)
        or re.search(r"\bwaitfor\s+delay\b", normalized)
    ):
        return False, "TIME_BASED_EXECUTION"

    def literal_value(token: str):
        match = re.fullmatch(r"__str(\d+)__", token)
        if match:
            return "string", strings[int(match.group(1))]
        if re.fullmatch(r"\d+(?:\.\d+)?", token):
            return "number", str(float(token))
        return None

    # Boolean/tautology injection such as OR 1=1 or OR 'x'='x'.
    for index, token in enumerate(tokens):
        if token != "or":
            continue

        position = index + 1
        while position < len(tokens) and tokens[position] == "(":
            position += 1

        if position < len(tokens) and tokens[position] == "true":
            return False, "BOOLEAN_TAUTOLOGY"

        if position + 2 < len(tokens) and tokens[position + 1] == "=":
            left = literal_value(tokens[position])
            right = literal_value(tokens[position + 2])
            if left and right and left == right:
                return False, "BOOLEAN_TAUTOLOGY"

    return True, "SAFE"
