import threading
from collections import deque


class ResilientConnectionPool:
    def __init__(self, max_connections: int = 5, ping_timeout: float = 1.0):
        if max_connections < 1:
            raise ValueError("max_connections must be at least 1")

        self.max_connections = max_connections
        self.ping_timeout = ping_timeout
        self._lock = threading.Lock()
        self._next_id = 0
        self._available = deque()
        self._leased = {}

        for _ in range(max_connections):
            self._available.append(self._create_connection())

    def _create_connection(self) -> dict:
        conn = {"id": self._next_id, "alive": True}
        self._next_id += 1
        return conn

    def acquire(self) -> dict:
        with self._lock:
            if not self._available:
                raise RuntimeError("Pool exhausted")

            conn = self._available.popleft()
            self._leased[id(conn)] = conn
            return conn

    def release(self, conn: dict) -> None:
        with self._lock:
            leased_conn = self._leased.pop(id(conn), None)
            if leased_conn is None:
                raise ValueError("Connection was not acquired from this pool")

            self._available.append(leased_conn)

    def health_check_and_heal(self) -> int:
        healed = 0

        with self._lock:
            for conn in list(self._available) + list(self._leased.values()):
                if not conn.get("alive", False):
                    conn["id"] = self._next_id
                    self._next_id += 1
                    conn["alive"] = True
                    healed += 1

        return healed

    def close_all(self) -> None:
        with self._lock:
            self._available.clear()
            self._leased.clear()
