import ast


def prune_dead_code_and_imports(source_code: str) -> str:
    tree = ast.parse(source_code)

    used_names = {
        node.id
        for node in ast.walk(tree)
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Load)
    }

    class DeadCodePruner(ast.NodeTransformer):
        def visit_Module(self, node: ast.Module) -> ast.Module:
            node.body = self._prune_body(node.body, top_level=True)
            return node

        def _prune_body(self, body: list[ast.stmt], top_level: bool = False) -> list[ast.stmt]:
            pruned: list[ast.stmt] = []

            for statement in body:
                if isinstance(statement, ast.Import):
                    aliases = [
                        alias
                        for alias in statement.names
                        if (alias.asname or alias.name.split(".")[0]) in used_names
                    ]
                    if aliases:
                        statement.names = aliases
                        pruned.append(statement)
                    continue

                if isinstance(statement, ast.ImportFrom):
                    if any(alias.name == "*" for alias in statement.names):
                        pruned.append(statement)
                        continue

                    aliases = [
                        alias
                        for alias in statement.names
                        if (alias.asname or alias.name) in used_names
                    ]
                    if aliases:
                        statement.names = aliases
                        pruned.append(statement)
                    continue

                if (
                    top_level
                    and isinstance(statement, (ast.FunctionDef, ast.AsyncFunctionDef))
                    and statement.name.startswith("_")
                    and statement.name not in used_names
                ):
                    continue

                pruned.append(statement)

            return pruned

    tree = DeadCodePruner().visit(tree)
    ast.fix_missing_locations(tree)

    result = ast.unparse(tree)
    compile(result, "<pruned_code>", "exec")
    return result
