from copy import deepcopy
from typing import Any


class QuorumCluster:
    def __init__(self, node_ids: list[str]):
        if len(node_ids) != len(set(node_ids)):
            raise ValueError("node_ids must be unique")

        self.node_ids = list(node_ids)
        self.total_nodes = len(node_ids)
        self.quorum_threshold = self.total_nodes // 2 + 1
        self._state: dict[str, dict[str, Any]] = {
            node_id: {} for node_id in self.node_ids
        }
        self._partitions: tuple[tuple[str, ...], tuple[str, ...]] | None = None

    def partition(self, group_a: list[str], group_b: list[str]) -> None:
        group_a_set = set(group_a)
        group_b_set = set(group_b)
        cluster_nodes = set(self.node_ids)

        if group_a_set & group_b_set:
            raise ValueError("Partitions must not overlap")

        if group_a_set | group_b_set != cluster_nodes:
            raise ValueError("Partitions must contain every cluster node")

        if len(group_a_set) != len(group_a) or len(group_b_set) != len(group_b):
            raise ValueError("Partition node IDs must be unique")

        self._partitions = (tuple(group_a), tuple(group_b))

    def heal_partition(self) -> None:
        if self._partitions is None:
            return

        source_partition = max(self._partitions, key=len)
        source_node = source_partition[0] if source_partition else None

        if source_node is not None:
            committed_state = deepcopy(self._state[source_node])
            for node_id in self.node_ids:
                self._state[node_id] = deepcopy(committed_state)

        self._partitions = None

    def propose_write(
        self,
        from_node: str,
        key: str,
        value: Any,
    ) -> bool:
        if from_node not in self._state:
            raise ValueError(f"Unknown node: {from_node}")

        if self._partitions is None:
            active_partition = tuple(self.node_ids)
        else:
            active_partition = next(
                partition
                for partition in self._partitions
                if from_node in partition
            )

        if len(active_partition) < self.quorum_threshold:
            return False

        for node_id in active_partition:
            self._state[node_id][key] = deepcopy(value)

        return True

    def read_value(self, from_node: str, key: str) -> Any:
        if from_node not in self._state:
            raise ValueError(f"Unknown node: {from_node}")

        return deepcopy(self._state[from_node].get(key))
