import base64
import hashlib
import hmac
import json
import time


def verify_jwt(
    token: str,
    secret_key: str,
    allowed_algs: list[str] = ["HS256"],
) -> dict:
    def decode_segment(segment: str) -> bytes:
        padding = "=" * (-len(segment) % 4)
        try:
            return base64.b64decode(
                segment + padding,
                altchars=b"-_",
                validate=True,
            )
        except Exception as exc:
            raise ValueError("Invalid Base64 encoding") from exc

    parts = token.split(".")
    if len(parts) != 3:
        raise ValueError("Invalid JWT format")

    try:
        header = json.loads(decode_segment(parts[0]))
        payload = json.loads(decode_segment(parts[1]))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise ValueError("Invalid JWT JSON") from exc

    if not isinstance(header, dict) or not isinstance(payload, dict):
        raise ValueError("Invalid JWT contents")

    alg = header.get("alg")
    if not isinstance(alg, str) or alg not in allowed_algs:
        raise ValueError("Unapproved algorithm")

    hash_algorithms = {
        "HS256": hashlib.sha256,
        "HS384": hashlib.sha384,
        "HS512": hashlib.sha512,
    }

    hash_function = hash_algorithms.get(alg)
    if hash_function is None:
        raise ValueError("Unsupported algorithm")

    signature = decode_segment(parts[2])
    signing_input = f"{parts[0]}.{parts[1]}".encode("ascii")
    expected_signature = hmac.new(
        secret_key.encode("utf-8"),
        signing_input,
        hash_function,
    ).digest()

    if not hmac.compare_digest(signature, expected_signature):
        raise ValueError("Invalid signature")

    if "exp" in payload:
        exp = payload["exp"]
        if isinstance(exp, bool) or not isinstance(exp, (int, float)):
            raise ValueError("Invalid expiration")
        if exp <= time.time():
            raise ValueError("Token expired")

    return payload
