def is_safe_sql_query(query: str) -> tuple[bool, str]:
    import re

    if not isinstance(query, str) or not query.strip():
        return False, "INVALID_QUERY"

    masked = []
    comment_free = []
    length = len(query)
    index = 0

    while index < length:
        char = query[index]

        if query.startswith("--", index):
            if index > 0 and query[index - 1] in "'\"`":
                return False, "BOOLEAN_TAUTOLOGY"

            newline = query.find("\n", index + 2)
            index = length if newline == -1 else newline
            masked.append(" ")
            continue

        if query.startswith("/*", index):
            end = query.find("*/", index + 2)
            if end == -1:
                return False, "INVALID_QUERY"

            body = query[index + 2:end]
            if body.startswith("!"):
                return False, "EXECUTABLE_COMMENT"

            previous = query[index - 1] if index > 0 else ""
            following_index = end + 2
            following = query[following_index] if following_index < length else ""

            if previous.isalpha() and following.isalpha():
                return False, "COMMENT_OBFUSCATION"

            masked.append(" ")
            index = end + 2
            continue

        dollar_tag = None
        if char == "$":
            match = re.match(r"\$(?:[A-Za-z_][A-Za-z0-9_]*)?\$", query[index:])
            if match:
                dollar_tag = match.group(0)

        if dollar_tag:
            end = query.find(dollar_tag, index + len(dollar_tag))
            if end == -1:
                return False, "INVALID_QUERY"

            end += len(dollar_tag)
            masked.append(" __sql_string__ ")
            comment_free.append("__sql_string__")
            index = end
            continue

        if char in "'\"`":
            quote = char
            end = index + 1
            closed = False

            while end < length:
                if query[end] == "\\" and end + 1 < length:
                    end += 2
                    continue

                if query[end] == quote:
                    if end + 1 < length and query[end + 1] == quote:
                        end += 2
                        continue

                    end += 1
                    closed = True
                    break

                end += 1

            if not closed:
                return False, "INVALID_QUERY"

            masked.append(" __sql_string__ ")
            comment_free.append("__sql_string__")
            index = end
            continue

        if char == "[":
            end = query.find("]", index + 1)
            if end == -1:
                return False, "INVALID_QUERY"

            masked.append(" __sql_identifier__ ")
            comment_free.append("__sql_identifier__")
            index = end + 1
            continue

        masked.append(char)
        comment_free.append(char)
        index += 1

    normalized = re.sub(r"\s+", " ", "".join(masked)).strip()
    compact = re.sub(r"\s+", " ", "".join(comment_free)).strip()

    if re.search(r";\s*\S", normalized, re.IGNORECASE):
        return False, "STACKED_QUERY"

    union_pattern = r"\bunion\b\s+(?:all\s+)?select\b"
    if re.search(union_pattern, normalized, re.IGNORECASE) or re.search(
        union_pattern, compact, re.IGNORECASE
    ):
        return False, "UNION_EXFILTRATION"

    time_patterns = (
        r"\b(?:pg_sleep|sleep|benchmark)\s*\(",
        r"\bwaitfor\s+delay\b",
    )
    if any(
        re.search(pattern, text, re.IGNORECASE)
        for pattern in time_patterns
        for text in (normalized, compact)
    ):
        return False, "TIME_BASED_INJECTION"

    atom = r"(?:__sql_string__|[-+]?(?:\d+(?:\.\d*)?|\.\d+)|true|false|null)"
    tautology_pattern = re.compile(
        rf"(?<![A-Za-z0-9_])(?:or|and)\s*({atom})\s*=\s*({atom})",
        re.IGNORECASE,
    )

    for text in (normalized, compact):
        for match in tautology_pattern.finditer(text):
            if match.group(1).lower() == match.group(2).lower():
                return False, "BOOLEAN_TAUTOLOGY"

    return True, "SAFE"
