from collections import deque
from threading import RLock
from typing import Dict


class ResilientConnectionPool:
    def __init__(self, max_connections: int = 5, ping_timeout: float = 1.0):
        if not isinstance(max_connections, int) or isinstance(max_connections, bool):
            raise TypeError("max_connections must be an integer")
        if max_connections <= 0:
            raise ValueError("max_connections must be greater than zero")
        if ping_timeout < 0:
            raise ValueError("ping_timeout must be non-negative")

        self.max_connections = max_connections
        self.ping_timeout = ping_timeout
        self._lock = RLock()
        self._next_id = 1
        self._connections = []
        self._available = deque()
        self._in_use = set()

        for _ in range(max_connections):
            conn = self._new_connection()
            self._connections.append(conn)
            self._available.append(conn)

    def _new_connection(self) -> Dict[str, object]:
        conn = {"id": self._next_id, "alive": True}
        self._next_id += 1
        return conn

    def acquire(self) -> dict:
        with self._lock:
            if not self._available:
                raise RuntimeError("Pool exhausted")

            conn = self._available.popleft()
            self._in_use.add(id(conn))
            return conn

    def release(self, conn: dict) -> None:
        with self._lock:
            if not isinstance(conn, dict):
                raise TypeError("conn must be a dictionary")

            identity = id(conn)
            if identity not in self._in_use:
                raise RuntimeError("Connection was not acquired from this pool")

            if not any(existing is conn for existing in self._connections):
                raise RuntimeError("Connection pool is closed")

            self._in_use.remove(identity)
            self._available.append(conn)

    def health_check_and_heal(self) -> int:
        with self._lock:
            healed = 0

            for conn in self._connections:
                if conn.get("alive") is False:
                    replacement = self._new_connection()
                    conn["id"] = replacement["id"]
                    conn["alive"] = replacement["alive"]
                    healed += 1

            return healed

    def close_all(self) -> None:
        with self._lock:
            for conn in self._connections:
                conn["alive"] = False

            self._connections.clear()
            self._available.clear()
            self._in_use.clear()
