import ast


def prune_dead_code_and_imports(source_code: str) -> str:
    tree = ast.parse(source_code)

    def referenced_names(node: ast.AST) -> set[str]:
        return {
            child.id
            for child in ast.walk(node)
            if isinstance(child, ast.Name) and isinstance(child.ctx, ast.Load)
        }

    # Remove unreferenced private functions defined directly in the module.
    names_used = referenced_names(tree)
    tree.body = [
        node
        for node in tree.body
        if not (
            isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))
            and node.name.startswith("_")
            and node.name not in names_used
        )
    ]

    names_used = referenced_names(tree)

    class ImportPruner(ast.NodeTransformer):
        def visit_Import(self, node: ast.Import) -> ast.AST | None:
            kept = []

            for alias in node.names:
                bound_name = alias.asname or alias.name.split(".", 1)[0]
                if bound_name in names_used:
                    kept.append(alias)

            if not kept:
                return None

            node.names = kept
            return node

        def visit_ImportFrom(self, node: ast.ImportFrom) -> ast.AST | None:
            if any(alias.name == "*" for alias in node.names):
                return node

            kept = [
                alias
                for alias in node.names
                if (alias.asname or alias.name) in names_used
            ]

            if not kept:
                return None

            node.names = kept
            return node

    tree = ImportPruner().visit(tree)
    tree = ast.fix_missing_locations(tree)

    result = ast.unparse(tree)
    compile(result, "<pruned>", "exec")
    return result
